        <svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-6 9l2 2 4-4"/></svg>
      </div>
      <h3 class="text-xl font-bold text-emerald-900">Action Steps — Build your own enquiry-to-appointment journey</h3>
    </div>
    
    <div class="space-y-4">
      
      <div class="flex items-start gap-4 bg-white rounded-xl p-4 shadow-sm">
        <div class="w-10 h-10 rounded-full bg-emerald-500 text-white flex items-center justify-center font-bold text-lg flex-shrink-0">1</div>
        <div>
          <p class="font-semibold text-slate-900">Set up weekly tracking</p>
          <p class="text-slate-600 text-sm">Create a simple tracker for form submissions, emails sent, replies, bookings, and unsubscribes.</p>
        </div>
      </div>
      <div class="flex items-start gap-4 bg-white rounded-xl p-4 shadow-sm">
        <div class="w-10 h-10 rounded-full bg-emerald-500 text-white flex items-center justify-center font-bold text-lg flex-shrink-0">2</div>
        <div>
          <p class="font-semibold text-slate-900">Review common questions</p>
          <p class="text-slate-600 text-sm">Look at replies and identify questions your first email could answer better.</p>
        </div>
      </div>
      <div class="flex items-start gap-4 bg-white rounded-xl p-4 shadow-sm">
        <div class="w-10 h-10 rounded-full bg-emerald-500 text-white flex items-center justify-center font-bold text-lg flex-shrink-0">3</div>
        <div>
          <p class="font-semibold text-slate-900">Make one small improvement</p>
          <p class="text-slate-600 text-sm">Choose one change to test — a clearer subject line, a better booking link placement, or an added FAQ sentence.</p>
        </div>
      </div>
    </div>
  </div>
</div>',
      title = 'Improve based on real conversations',
      lesson_number = 6,
      sort_order = 6,
      updated_at = NOW()
    WHERE id = v_lesson_id;
    
    RAISE NOTICE 'Updated lesson: Improve based on real conversations';
  END IF;

END $$;


-- Insert Quiz Questions for Lesson: Improve based on real conversations

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 17 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 17 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'improve-based-on-conversations' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson improve-based-on-conversations not found in module 17';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What should you review weekly to improve your follow-up journey?', 
    '["Only the number of bookings","Form submissions, emails sent, replies, bookings, unsubscribes, and common questions","Only the workflow execution history","Only the calendar availability"]'::jsonb,
    'Form submissions, emails sent, replies, bookings, unsubscribes, and common questions',
    'Review form submissions, first emails sent, replies and bookings, unsubscribes and complaints, and common questions. This gives a complete picture of how the journey is performing.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Why should you not compare raw booking counts alone?', 
    '["Because bookings are not important","Because you must also consider the number and quality of enquiries","Because the workflow does not track bookings","Because booking counts are always inaccurate"]'::jsonb,
    'Because you must also consider the number and quality of enquiries',
    'Raw booking counts without context can be misleading. A drop in bookings might reflect fewer or lower-quality enquiries, not a broken follow-up process. Always consider enquiry volume and quality.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What is the recommended approach to improving the follow-up journey?', 
    '["Redesign the entire workflow every week","Start with an observation, make one small change, then check results","Copy a competitor''s workflow exactly","Add more emails and reminders"]'::jsonb,
    'Start with an observation, make one small change, then check results',
    'Start with an observation from your weekly review, make one small change, then check results. This controlled approach helps you understand what actually improves performance.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;
